import React from "react";

export default function PrivacyPolicy() {
  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Privacy Policy</h1>
      <p style={styles.date}>Last Updated: {new Date().toDateString()}</p>

      <Section title="1. Information We Collect">
        We collect personal details such as your name, email, phone number,
        and address to provide better services.
      </Section>

      <Section title="2. How We Use Your Information">
        Your data is used to process orders, improve user experience,
        and provide customer support.
      </Section>

      <Section title="3. Data Protection">
        We use secure technologies and encryption to protect your data.
      </Section>

      <Section title="4. Cookies">
        We use cookies to enhance your browsing experience and analyze traffic.
      </Section>

      <Section title="5. Third-Party Services">
        We may share data with delivery partners and payment gateways
        only for service fulfillment.
      </Section>

      <Section title="6. Your Rights">
        You can request to access, update, or delete your data anytime.
      </Section>

      <Section title="7. Contact Us">
        Email: support@thezuro.com
      </Section>
    </div>
  );
}

function Section({ title, children }) {
  return (
    <div style={{ marginBottom: 20 }}>
      <h3 style={{ color: "#9400D3" }}>{title}</h3>
      <p style={{ lineHeight: 1.6 }}>{children}</p>
    </div>
  );
}

const styles = {
  container: {
    maxWidth: "900px",
    margin: "40px auto",
    padding: "20px",
    fontFamily: "Arial",
    background: "#fff",
    borderRadius: "10px",
    boxShadow: "0 5px 20px rgba(0,0,0,0.08)"
  },
  title: {
    fontSize: "32px",
    fontWeight: "bold",
    marginBottom: "10px"
  },
  date: {
    color: "#666",
    marginBottom: "30px"
  }
};
